B.aRw=new A.iB('Bu kullan\u0131m ko\u015fullar\u0131, Koala by evlumba uygulamas\u0131n\u0131 ("Uygulama") kullan\u0131m\u0131n\u0131z\u0131 d\xfczenler. Uygulamay\u0131 kullanarak bu ko\u015fullar\u0131 kabul etmi\u015f say\u0131l\u0131rs\u0131n\u0131z.',null)
B.aRz=new A.iB("Son g\xfcncelleme: 18 Mart 2026",null)
B.aSZ=new A.j2("Hizmet Tan\u0131m\u0131",null)
B.aRs=new A.iB("Koala, yapay zeka destekli bir mekan analiz uygulamas\u0131d\u0131r. Kullan\u0131c\u0131lar soru foto\u011fraf\u0131 \xe7ekerek ad\u0131m ad\u0131m \xe7\xf6z\xfcm alabilir. Uygulama 9 farkl\u0131 bran\u015fta AI destekli \xf6\u011fretim hizmeti sunar.",null)
B.aSV=new A.j2("Hesap ve Kay\u0131t",null)
B.aOX=new A.eE("Uygulamay\u0131 kullanmak i\xe7in Google veya telefon numaras\u0131 ile hesap olu\u015fturman\u0131z gerekir",null)
B.aP_=new A.eE("Hesap bilgilerinizin do\u011fru ve g\xfcncel olmas\u0131ndan siz sorumlusunuz",null)
B.aOJ=new A.eE("Hesab\u0131n\u0131z\u0131n g\xfcvenli\u011finden siz sorumlusunuz",null)
B.aT3=new A.j2("Kredi Sistemi",null)
B.aOH=new A.eE("Her yeni kullan\u0131c\u0131ya 10 \xfccretsiz kredi verilir",null)
B.aP5=new A.eE("Her mekan analizi 1 kredi harcar",null)
B.aP4=new A.eE("Ek kredi uygulama i\xe7i sat\u0131n alma ile edinilebilir",null)
B.aP3=new A.eE("Sat\u0131n al\u0131nan krediler iade edilemez",null)
B.aSW=new A.j2("Kabul Edilebilir Kullan\u0131m",null)
B.aRp=new A.iB("Uygulamay\u0131 yaln\u0131zca ki\u015fisel mekan analizi ama\xe7l\u0131 kullanabilirsiniz. A\u015fa\u011f\u0131daki davran\u0131\u015flar yasakt\u0131r:",null)
B.aP2=new A.eE("Uygulamay\u0131 k\xf6t\xfcye kullanmak veya ba\u015fkalar\u0131n\u0131n kullan\u0131m\u0131n\u0131 engellemek",null)
B.aOW=new A.eE("Otomatik botlar veya scraper kullanmak",null)
B.aOZ=new A.eE("Uygulamay\u0131 s\u0131nav s\u0131ras\u0131nda kopya \xe7ekmek i\xe7in kullanmak",null)
B.aOT=new A.eE("Yasalara ayk\u0131r\u0131 i\xe7erik g\xf6ndermek",null)
B.aSX=new A.j2("Fikri M\xfclkiyet",null)
B.aRu=new A.iB("Uygulama ve i\xe7eri\u011fi Evlumba Software'a aittir. AI taraf\u0131ndan \xfcretilen \xe7\xf6z\xfcmler e\u011fitim ama\xe7l\u0131d\u0131r ve do\u011frulu\u011fu garanti edilmez.",null)
B.aST=new A.j2("Sorumluluk S\u0131n\u0131rlamas\u0131",null)
B.aRD=new A.iB('Koala bir mekan analiz asistan\u0131d\u0131r, profesyonel i\xe7 mimar\u0131n yerini almaz. AI \xf6nerilerinin do\u011frulu\u011fu garanti edilmez. Uygulama "oldu\u011fu gibi" sunulur.',null)
B.aT0=new A.j2("De\u011fi\u015fiklikler",null)
B.aRv=new A.iB("Bu ko\u015fullar\u0131 zaman zaman g\xfcncelleyebiliriz. \xd6nemli de\u011fi\u015fikliklerde uygulama i\xe7i bildirim yapaca\u011f\u0131z.",null)
B.aRC=new A.iB("Kullan\u0131m ko\u015fullar\u0131yla ilgili sorular\u0131n\u0131z i\xe7in:\nE-posta: info@evlumba.com\nWeb: evlumba.com\nGeli\u015ftirici: Evlumba Software",null)
